    def test_invalid_location_valid_year_route(self):

        #sets up a special test app
        self.app = app.test_client() 

        #test app returns TestResponse object
        #TestResponse has webpage in .data

        '''Checking if it is outputting the right thing When no valid location is inputted'''
        response = self.app.get('/Carleton/2000', follow_redirects=True) 
        self.assertEqual(b"Country or region not found, please try again.", response.data) 

    def test_valid_location_invalid_year_route_correct(self):

        #sets up a special test app
        self.app = app.test_client() 

        #test app returns TestResponse object
        #TestResponse has webpage in .data

        '''Checking if it is outputting the right thing When no valid year is inputted'''
        response = self.app.get('/Andorra/1999', follow_redirects=True) 
        self.assertEqual(b"Year outside range, please specify a year in the range 2000-2024", response.data) 

